proc = subprocess.Popen([r'C:/Users/Administrador/AppData/Local/OpenAI/Codex/bin/08d187884f2330d1/codex.exe','app-server','--stdio'], cwd=root, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, text=True, encoding='utf-8', creationflags=subprocess.CREATE_NO_WINDOW)
responses = queue.Queue()
def collect():
    for line in proc.stdout:
        try: responses.put(json.loads(line))
        except json.JSONDecodeError: pass
threading.Thread(target=collect, daemon=True).start()
def send(data):
    proc.stdin.write(json.dumps(data)+'\n'); proc.stdin.flush()
def request(n, method, params):
    send({'id':n,'method':method,'params':params})
    deadline = time.monotonic()+25
    while time.monotonic()<deadline:
        msg = responses.get(timeout=max(0.1, deadline-time.monotonic()))
        if msg.get('id') == n:
            if 'error' in msg: raise RuntimeError(json.dumps(msg['error']))
            return msg['result']
    raise TimeoutError(method)
def project_hooks(result):
    return [h for entry in result['data'] for h in entry['hooks'] if str(h.get('sourcePath','')).replace('\\','/').lower() == str(hooks_path).replace('\\','/').lower()]
try:
    request(1,'initialize',{'clientInfo':{'name':'entire_hook_setup','version':'1.0'},'capabilities':{'experimentalApi':True}})
    send({'method':'initialized','params':{}})
    result = request(2,'hooks/list',{'cwds':[str(root)]})
    assert all(not entry.get('errors') for entry in result['data']), 'Hook discovery errors'
    hooks = project_hooks(result)
    allowed = {'session-start','session-end','user-prompt-submit','post-tool-use','stop','subagent-start','subagent-stop'}
    prefix = r'C:\Users\Administrador\.local\bin\entire.exe hooks codex '
    assert len(hooks) == 7, 'Expected seven project hooks, got '+str(len(hooks))
    assert {h['command'].removeprefix(prefix) for h in hooks} == allowed
    for h in hooks:
