        assert after_states[key] == value, 'Existing hook state changed: '+key
    for h in hooks:
        assert after_states[h['key']]['trusted_hash'] == h['currentHash']
    for data in (before, after):
        for h in hooks: data.get('hooks',{}).get('state',{}).pop(h['key'],None)
